/* A2K Build 260 — Account Removal Wizard.
   Reuses the approved Member Setup Wizard artwork and vintage visual system.
   All deletion permission checks and password verification run on the server. */
(function(){
'use strict';
const $=id=>document.getElementById(id);
const make=(tag,cls,txt)=>{
  const el=document.createElement(tag);
  if(cls)el.className=cls;
  if(txt!==undefined)el.textContent=String(txt);
  return el;
};
let modal=null,preview=null,targetId=null,busy=false;
let stage=0,password='',confirmation='',reasonText='';
const steps=['Review Content','Verify Identity','Confirm Deletion'];
function client(){return typeof authClient!=='undefined'?authClient:null}
function actor(){return typeof authUser!=='undefined'?authUser:null}
function protect(member){
 return !member||member.id===actor()?.id||
 ['founder','super_admin','admin','moderator','owner'].includes(member.role)||
 Number(member.member_number)===1;
}
async function request(action,props){
 if(!client()||!actor())throw Error('Sign in again to continue.');
 const {data,error}=await client().functions.invoke('a2k-member-deletion',{body:{action,...props}});
 if(error){
  let msg=error.message||'Request failed.';
  try{const details=await error.context?.json?.();if(details?.error)msg=details.error}catch(_){}
  throw Error(msg);
 }
 if(data?.error)throw Error(data.error);
 return data;
}
const ART_LOGO="data:image/webp;base64,";
const ART_CROWD="data:image/webp;base64,";

let elements={};
function cleanup(){
 const previous=modal;
 modal=null;preview=null;targetId=null;stage=0;password='';confirmation='';reasonText='';
 elements={};busy=false;
 if(previous?.open)previous.close();
 previous?.remove();
}
function close(){if(!busy)cleanup();}
function status(message){
 const box=elements.status;
 if(box)box.textContent=message||'';
}
function makePicture(src,cls,description){
 const img=make('img',cls);
 img.src=src;img.alt=description;img.decoding='async';
 return img;
}
function buildDialog(){
 const dialog=make('dialog','a2k-deletion-wizard');
 dialog.id='a2k-delete-account-dialog';
 dialog.setAttribute('aria-labelledby','a2k-deletion-title');
 const bar=make('header','a2k-deletion-titlebar');
 const title=make('div','a2k-deletion-app-title');
 title.id='a2k-deletion-title';
 title.append(make('strong','a2k-deletion-app-brand','Addicted to Karaoke'),
  make('span','a2k-deletion-app-subtitle','ACCOUNT REMOVAL WIZARD'));
 bar.append(title);
 bar.append(make('span','a2k-deletion-mode','ACCOUNT SECURITY'));
 const middle=make('div','a2k-deletion-layout');
 const sidebar=make('aside','a2k-deletion-sidebar');
 sidebar.append(makePicture(ART_LOGO,'a2k-deletion-brand','Addicted to Karaoke vintage microphone artwork'));
 sidebar.append(make('h2','a2k-deletion-side-title','Account Removal Wizard'));
 const timeline=make('div','a2k-deletion-timeline');
 for(let i=0;i<steps.length;i++){
  const line=make('div','a2k-deletion-timeline-item');
  line.dataset.step=String(i);
  line.append(make('span','a2k-deletion-timeline-dot'),make('strong','',steps[i]));
  timeline.append(line);
 }
 sidebar.append(timeline,makePicture(ART_CROWD,'a2k-deletion-crowd','Decorative karaoke crowd'));
 sidebar.append(make('span','a2k-deletion-side-foot','PRIVATE & SECURE'));
 const inner=make('section','a2k-deletion-right');
 const mobile=make('div','a2k-deletion-mobile-progress');
 for(let i=0;i<steps.length;i++){
  const dot=make('span','a2k-deletion-progress-dot');
  dot.dataset.step=String(i);
  mobile.append(dot);
 }
 const stepTitle=make('span','a2k-deletion-progress-label','');
 mobile.append(stepTitle);
 const content=make('div','a2k-deletion-stage');content.id='a2k-deletion-stage';
 const error=make('p','a2k-deletion-error');error.id='a2k-delete-error';
 error.setAttribute('role','status');error.setAttribute('aria-live','polite');
 inner.append(mobile,content,error);
 middle.append(sidebar,inner);
 const footer=make('footer','a2k-deletion-footer');
 const progressWrap=make('div','a2k-deletion-footer-progress');
 const progress=make('strong','a2k-deletion-footer-label','Step 1 of 3');
 const build=make('small','a2k-deletion-footer-build');
 build.textContent='Website Build '+(typeof SITE_BUILD_VERSION!=='undefined'?SITE_BUILD_VERSION:(document.querySelector('[data-build-version]')?.textContent.trim()||'—'));
 progressWrap.append(progress,build);
 const right=make('div','a2k-deletion-footer-actions');
 const cancel=make('button','a2k-deletion-btn a2k-deletion-btn-subtle','Cancel');
 const back=make('button','a2k-deletion-btn a2k-deletion-btn-subtle','Previous');
 const next=make('button','a2k-deletion-btn a2k-deletion-btn-primary','Continue');
 for(const btn of [cancel,back,next])btn.type='button';
 cancel.onclick=close;
 back.onclick=()=>{if(!busy&&stage>0){stage--;renderStage();}};
 next.onclick=()=>void nextStage();
 right.append(cancel,back,next);
 footer.append(progressWrap,right);
 dialog.append(bar,middle,footer);
 dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
 dialog.addEventListener('close',()=>{if(dialog===modal&&!busy)cleanup();});
 elements={content,error,status:error,progress,build,stepTitle,back,next,cancel,sidebar,timeline,mobile};
 return dialog;
}
function paragraph(parent,cls,text){
 const p=make('p',cls,text);parent.append(p);return p;
}
function cardTitle(parent,title,sub){
 const h=make('h2','a2k-deletion-section-title',title);parent.append(h);
 if(sub)paragraph(parent,'a2k-deletion-section-lede',sub);
}
function infoCard(parent,title,description,kind){
 const box=make('div','a2k-deletion-info-card'+(kind?' '+kind:''));
 box.append(make('strong','',title),make('p','',description));
 parent.append(box);
 return box;
}
function field(parent,title,id,kind,placeholder,value){
 const label=make('label','a2k-deletion-field');
 const strong=make('strong','',title);
 const input=make(kind==='textarea'?'textarea':'input','a2k-deletion-input');
 input.id=id;
 if(kind==='textarea'){input.rows=3;input.maxLength=400;}
 else {input.type=kind||'text';input.autocomplete='off';input.spellcheck=false;}
 input.placeholder=placeholder||'';
 input.value=value||'';
 label.append(strong,input);parent.append(label);
 return input;
}
function impactCard(parent,label,value){
 const tile=make('div','a2k-deletion-impact-tile');
 tile.append(make('strong','a2k-deletion-impact-number',String(value)),
   make('span','a2k-deletion-impact-label',label));
 parent.append(tile);
}
function renderReview(main){
 const isSelf=preview.kind==='self';
 cardTitle(main,'Review What Will Be Removed',
  'See exactly which A2K records would be removed before you continue.');
 const person=make('div','a2k-deletion-person');
 person.append(make('span','a2k-deletion-person-mark','♪'));
 const who=make('div','');
 who.append(make('strong','',isSelf?'Your A2K Membership':preview.name||'Karaoke Member'));
 who.append(make('small','',preview.member_number?
  'Member #'+String(preview.member_number).padStart(6,'0'):'Registered member'));
 person.append(who);main.append(person);
 const box=make('div','a2k-deletion-stage-box');
 box.append(make('h3','','Associated Content'));
 const grid=make('div','a2k-deletion-impact-grid');
 const data=preview.content||{};
 for(const [label,key] of [['Venues','venues'],['Venue Reviews','venue_reviews'],
  ['KJ Reviews','kj_reviews'],['Venue Photos','photos'],
  ['Songs','songs'],['Favorites','favorites']])
   impactCard(grid,label,Number(data[key]||0));
 box.append(grid);
 const additions=[
  ['KJ hosting requests','host_requests'],['Approved schedules to review','approved_kj_schedule_requests'],
  ['Venue suggestions','venue_suggestions'],['Ownership claims','venue_claims'],
  ['Special events','special_events'],['Event submissions','special_event_suggestions'],
  ['Venue reports','venue_reports']
 ];
 const other=additions.filter(([_,key])=>Number(data[key]||0)>0);
 if(Number(preview.storage_count||0)>0)other.push(['Uploaded files','storage_count']);
 if(other.length){
  const details=make('div','a2k-deletion-secondary');
  details.append(make('h4','','Additional records'));
  for(const [name,key] of other){
   const row=make('div','a2k-deletion-secondary-row');
   row.append(make('span','',name),
     make('strong','',String(key==='storage_count'?preview.storage_count:data[key])));
   details.append(row);
  }
  box.append(details);
 }
 main.append(box);
 const outside=Number(data.account_reviews_by_others||0)+Number(data.kj_reviews_by_others||0);
 if(outside){
  infoCard(main,'Other members’ reviews are affected',
   outside+' review(s) written by other members are linked to content being deleted.','warning');
 }
 if(Number(data.approved_kj_schedule_requests||0)>0){
  infoCard(main,'Approved schedules may need attention',
   'Approved KJ schedules on surviving venues may require administrator review.','warning');
 }
 infoCard(main,'This action cannot be undone',
  'Your A2K account and associated contributions cannot be restored by signing up again.','neutral');
}
function renderVerify(main){
 cardTitle(main,'Verify Your Identity',
  'A2K requires an additional check before permanent account removal.');
 const box=make('div','a2k-deletion-stage-box');
 const method=preview.verification_method||'confirmation';
 if(method==='password'){
  box.append(make('h3','','Confirm Your Password'));
  paragraph(box,'a2k-deletion-field-description',
   'Please enter the password for YOUR signed-in A2K account'+
    (preview.kind==='management'?', not the member being removed.':'.'));
  const email=actor()?.email||'';
  if(email)paragraph(box,'a2k-deletion-account-email',email);
  const pass=field(box,'Current A2K password','a2k-delete-password',
   'password','Enter your password',password);
  pass.autocomplete='current-password';
  pass.oninput=()=>{password=pass.value;status('');};
 }else{
  box.append(make('h3','','Google Sign-In Account'));
  paragraph(box,'a2k-deletion-field-description',
   'This account uses Google sign-in. A2K will NEVER ask for your Google password.');
  infoCard(box,'Confirmation method',
   'Continue to the final step, then type the exact deletion phrase.','neutral');
 }
 main.append(box);
 infoCard(main,'Your information stays private',
  'Passwords are verified by the server when you confirm deletion. A2K does not save your password.','neutral');
}
function renderConfirm(main){
 cardTitle(main,'Confirm Permanent Deletion',
  'This is the final step. Please review the account name before continuing.');
 const account=make('div','a2k-deletion-stage-box');
 account.append(make('h3','',preview.kind==='self'?
  'Delete My A2K Account':'Delete '+(preview.name||'This Member')));
 paragraph(account,'a2k-deletion-field-description',
  'This permanently removes the account and the content shown in Step 1.');
 const exact=preview.kind==='self'?'DELETE MY ACCOUNT':'DELETE MEMBER';
 const phrase=field(account,'Type '+exact+' to confirm','a2k-delete-confirm',
  'text',exact,confirmation);
 phrase.autocomplete='off';
 phrase.oninput=()=>{confirmation=phrase.value;status('');};
 if(preview.kind==='management'){
  const reason=field(account,'Reason for removal (required)','a2k-delete-reason',
   'textarea','Explain why this member is being removed',reasonText);
  reason.oninput=()=>{reasonText=reason.value;status('');};
 }
 main.append(account);
 infoCard(main,'Last chance to cancel',
  'Choose Cancel to leave everything untouched, or Delete Permanently to finish.','warning');
}
function renderStage(){
 if(!modal||!elements.content)return;
 elements.content.replaceChildren();
 elements.content.classList.toggle('a2k-deletion-review-stage',stage===0&&!!preview);
 status('');
 elements.timeline.querySelectorAll('[data-step]').forEach(el=>{
  const i=Number(el.dataset.step);
  el.classList.toggle('current',i===stage);
  el.classList.toggle('completed',i<stage);
  if(i===stage)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');
 });
 elements.mobile.querySelectorAll('[data-step]').forEach(el=>{
  const i=Number(el.dataset.step);el.classList.toggle('current',i===stage);
 });
 elements.stepTitle.textContent=steps[stage];
 elements.progress.textContent='Step '+(stage+1)+' of '+steps.length;
 elements.back.hidden=stage===0;
 elements.next.disabled=!preview||busy;
 elements.next.textContent=stage===2?'Delete Permanently':'Continue';
 elements.next.classList.toggle('a2k-deletion-btn-danger',stage===2);
 if(!preview){
  cardTitle(elements.content,'Checking Account','Looking up the records associated with this account…');
  return;
 }
 if(stage===0)renderReview(elements.content);
 if(stage===1)renderVerify(elements.content);
 if(stage===2)renderConfirm(elements.content);
 elements.content.scrollTop=0;
}
async function begin(target){
 if(busy)return;
 if(modal)cleanup();
 targetId=target;
 stage=0;password='';confirmation='';reasonText='';
 modal=buildDialog();
 document.body.append(modal);
 modal.showModal();
 renderStage();
 try{
  const response=await request('preview',{target});
  if(!modal?.open||targetId!==target)return;
  if(!response?.preview||response.preview.target!==target)
    throw Error('A2K could not verify this member account.');
  preview=response.preview;
  renderStage();
 }catch(e){
  status(e.message||'Could not load the account. Try again.');
  elements.next.disabled=true;
 }
}
async function nextStage(){
 if(busy||!preview)return;
 if(stage===1&&preview.verification_method==='password'&&!password){
  status('Enter your A2K account password to continue.');return;
 }
 if(stage<2){stage++;renderStage();return;}
 const exact=preview.kind==='self'?'DELETE MY ACCOUNT':'DELETE MEMBER';
 if(confirmation!==exact){status('Type '+exact+' exactly to proceed.');return;}
 if(preview.kind==='management'&&reasonText.trim().length<5){
  status('Please enter a reason of at least five characters.');return;
 }
 await execute();
}
async function execute(){
 if(!preview||!modal||busy)return;
 const target=targetId;
 busy=true;
 elements.next.disabled=true;
 elements.back.disabled=true;
 elements.cancel.disabled=true;
 status('Verifying your identity and processing the account removal…');
 try{
  const self=preview.kind==='self';
  const result=await request('delete',{
   target,signature:preview.signature,
   confirmation,self,reason:reasonText.trim(),
   password:preview.verification_method==='password'?password:undefined,
  });
  if(!result?.deleted)throw Error('Account removal was not confirmed.');
  busy=false;
  cleanup();
  if(self){
   try{await client()?.auth.signOut()}catch(e){console.warn('A2K sign-out',e)}
   location.replace(location.origin+'/?account=deleted');
  }else{
   if(typeof managementMemberBack==='function')managementMemberBack();
   if(typeof managementUsersLoad==='function')void managementUsersLoad();
   const feedback=$('mg-status');
   if(feedback)feedback.textContent='Member account and associated content deleted.';
  }
 }catch(e){
  busy=false;
  password=''; // Do not keep any failed or used credential in memory.
  elements.next.disabled=false;elements.back.disabled=false;elements.cancel.disabled=false;
  status(e.message||'Account removal failed. The deletion was not confirmed.');
 }
}
function mountManagement(){
  const details=$('management-member-details');
  if(!details||$('a2k-management-delete-entry'))return;
  const wrap=make('section','mg2-section a2k-management-delete');wrap.id='a2k-management-delete-entry';
  const heading=make('div','mg2-section-top');heading.append(make('h3','', 'Account Removal'));
  const note=make('p','a2k-delete-note','Remove a member and the content they submitted. A preview and confirmation are required.');
  const deleteButton=make('button','a2k-delete-management-button','Delete Member');
  deleteButton.type='button';
  deleteButton.onclick=()=>{const member=typeof managementSelectedMember!=='undefined'?managementSelectedMember:null;
    if(member&&!protect(member))void begin(member.id);};
  wrap.append(heading,note,deleteButton);
  const anchor=$('mg2-history-panel')?.closest('.mg2-disclosure')||$('mg2-permissions');
  if(anchor?.parentNode)anchor.insertAdjacentElement('afterend',wrap);
  else details.append(wrap);
  function refresh(){
    const member=typeof managementSelectedMember!=='undefined'?managementSelectedMember:null;
    const blocked=protect(member);
    wrap.hidden=details.hidden;
    deleteButton.disabled=blocked;
    note.textContent=blocked?'This account is protected. Founder, administrator and your own account cannot be deleted here.':
      'Delete '+(member?.stage_name||'this member')+' and their contributions after reviewing the complete impact.';
  }
  new MutationObserver(refresh).observe(details,{attributes:true,attributeFilter:['hidden']});
  refresh();
}
function mountSelf(){
  if($('a2k-self-delete-entry'))return;
  const settings=$('a2k-profile-settings')?.querySelector('.a2k-profile-settings-panel');
  if(!settings)return;
  const section=make('section','a2k-delete-self');section.id='a2k-self-delete-entry';
  const heading=make('div','profile-section-top');heading.append(make('strong','','Account & Data'));
  const note=make('p','a2k-delete-note','Permanently remove your A2K account, reviews, photos, songs and venues you created. You can see the impact before confirming.');
  const btn=make('button','a2k-delete-self-button','Delete My Account');
  btn.type='button';btn.onclick=()=>{if(actor()?.id)void begin(actor().id)};
  section.append(heading,note,btn);settings.append(section);
  let checkedId=null,founderCheck=0;
  function refresh(){
    const uid=actor()?.id||null;
    btn.disabled=!uid;
    if(!uid){checkedId=null;return;}
    if(checkedId===uid)return;
    checkedId=uid;
    const seq=++founderCheck;
    if(!client())return;
    client().rpc('is_platform_founder').then(({data,error})=>{
      if(!section.isConnected||actor()?.id!==uid||seq!==founderCheck)return;
      if(error){btn.disabled=true;note.textContent='Unable to verify account privileges. Please refresh.';return;}
      btn.disabled=data===true;
      note.textContent=data===true
        ?'The Founder account is protected. Site ownership must be handled separately before it can be removed.'
        :'Permanently remove your A2K account, reviews, photos, songs and venues you created. You can see the impact before confirming.';
    }).catch(()=>{if(actor()?.id===uid)btn.disabled=true});
  }
  const profile=$('auth-profile');
  if(profile)new MutationObserver(refresh).observe(profile,{attributes:true,attributeFilter:['hidden','style']});
  new MutationObserver(refresh).observe($('a2k-profile-settings'),{attributes:true,attributeFilter:['open']});
  window.addEventListener('pageshow',refresh);
  refresh();
}
function install(){mountManagement();mountSelf();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});
else install();
})();
